    /// <summary>
    /// Returns information about a message with the callback button that originated a callback query; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Message> GetCallbackQueryMessageAsync(long chatId = default, long messageId = default, long callbackQueryId = default)
    {

           using var activity =  StartCallActivity("GetCallbackQueryMessageAsync", typeof(GetCallbackQueryMessage).FullName ?? "GetCallbackQueryMessageAsync");

           try
           {
             return client.GetCallbackQueryMessageAsync(chatId, messageId, callbackQueryId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
